import React from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { Code, Database, BarChart, Brain, Layout, Wrench } from 'lucide-react';

const Skills = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  const skillCategories = [
    {
      icon: Code,
      title: 'Languages',
      color: 'from-blue-500 to-cyan-500',
      skills: [
        { name: 'Python', level: 90 },
        { name: 'SQL (MySQL)', level: 85 },
      ],
    },
    {
      icon: Database,
      title: 'Data Science & Analysis',
      color: 'from-purple-500 to-pink-500',
      skills: [
        { name: 'Pandas', level: 90 },
        { name: 'NumPy', level: 85 },
        { name: 'Matplotlib', level: 90 },
        { name: 'Seaborn', level: 85 },
        { name: 'EDA', level: 88 },
        { name: 'Feature Engineering', level: 85 },
        { name: 'Statistical Modeling', level: 82 },
      ],
    },
    {
      icon: Brain,
      title: 'Machine Learning',
      color: 'from-orange-500 to-red-500',
      skills: [
        { name: 'Scikit-learn', level: 88 },
        { name: 'TensorFlow', level: 82 },
        { name: 'XGBoost', level: 85 },
        { name: 'Model Evaluation', level: 87 },
        { name: 'Hyperparameter Tuning', level: 83 },
      ],
    },
    {
      icon: Layout,
      title: 'Web & Deployment',
      color: 'from-indigo-500 to-purple-500',
      skills: [
        { name: 'FastAPI', level: 80 },
        { name: 'Streamlit', level: 85 },
      ],
    },
    {
      icon: Wrench,
      title: 'Tools & Technologies',
      color: 'from-pink-500 to-rose-500',
      skills: [
        { name: 'GitHub', level: 90 },
        { name: 'Jupyter Notebook', level: 95 },
        { name: 'VS Code', level: 95 },
      ],
    },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, translateY: 20 },
    visible: {
      opacity: 1,
      translateY: 0,
      transition: {
        duration: 0.5,
      },
    },
  };

  return (
    <section id="skills" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          ref={ref}
          initial="hidden"
          animate={inView ? 'visible' : 'hidden'}
          variants={containerVariants}
        >
          {/* Section Header */}
          <motion.div variants={itemVariants} className="text-center mb-16">
            <h2 className="section-title">Skills & Expertise</h2>
            <p className="section-subtitle max-w-2xl mx-auto">
              A comprehensive toolkit for data science, machine learning, and AI development
            </p>
          </motion.div>

          {/* Skills Grid */}
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {skillCategories.map((category) => (
              <motion.div
                key={category.title}
                variants={itemVariants}
                className="glass-card p-6 hover:scale-105 transition-transform duration-300"
              >
                {/* Category Header */}
                <div className="flex items-center gap-3 mb-6">
                  <div className={`p-3 rounded-lg bg-gradient-to-r ${category.color}`}>
                    <category.icon className="w-6 h-6 text-white" />
                  </div>
                  <h3 className="text-xl font-semibold">{category.title}</h3>
                </div>

                {/* Skills List */}
                <div className="space-y-4">
                  {category.skills.map((skill) => (
                    <div key={skill.name}>
                      <div className="flex justify-between mb-2">
                        <span className="text-sm font-medium text-gray-300">{skill.name}</span>
                        <span className="text-sm text-accent-400">{skill.level}%</span>
                      </div>
                      <div className="h-2 bg-dark-800 rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={inView ? { width: `${skill.level}%` } : { width: 0 }}
                          transition={{ duration: 1, delay: 0.2 }}
                          className={`h-full bg-gradient-to-r ${category.color}`}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              </motion.div>
            ))}
          </div>

          {/* Additional Info */}
          <motion.div variants={itemVariants} className="mt-12 text-center">
            <div className="glass-card p-8 max-w-3xl mx-auto">
              <h3 className="text-xl font-semibold mb-4 gradient-text">
                Continuous Learning & Growth
              </h3>
              <p className="text-gray-300 leading-relaxed">
                I'm constantly expanding my skill set through hands-on projects, online courses, 
                and staying updated with the latest research in AI and machine learning. My goal 
                is to bridge the gap between theoretical knowledge and practical application.
              </p>
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default Skills;
